def scan():
    docs = []
    for dirpath, dirnames, filenames in os.walk(MEMORY):
        for fn in sorted(filenames):
            if not fn.endswith(".md"):
                continue
            p = os.path.join(dirpath, fn)
            rel = os.path.relpath(p, ROOT).replace("\\", "/")
            try:
                text = open(p, encoding="utf-8", errors="replace").read()
            except OSError:
                continue
            headings = [HEADING_RE.match(l).group(1).strip() for l in text.splitlines()
                        if HEADING_RE.match(l)]
            words = [w.lower() for w in WORD_RE.findall(text) if w.lower() not in STOP]
            docs.append({"path": rel, "chars": len(text), "headings": headings[:40],
                         "top_terms": sorted(set(words))[:30]})
    return docs

def main():
    t0 = time.time()
    docs = scan()
    term_count = {}
    for d in docs:
        for t in set(d["top_terms"]):
            term_count[t] = term_count.get(t, 0) + 1
    hot = sorted(term_count.items(), key=lambda kv: (-kv[1], kv[0]))[:50]
    index = {"generated": time.strftime("%Y-%m-%d %H:%M:%S"), "doc_count": len(docs),
             "total_chars": sum(d["chars"] for d in docs), "hot_terms": hot,
             "docs": docs}
    out_json = os.path.join(HERE, "knowledge-index.json")
    json.dump(index, open(out_json, "w", encoding="utf-8"), indent=1)
    lines = ["# Knowledge Index Report", "", f"Generated {index['generated']}",
             f"Docs indexed: {len(docs)} | total chars: {index['total_chars']:,}",
             f"Build time: {time.time()-t0:.2f}s", "", "## Hot terms (doc frequency)", ""]
    for t, c in hot[:25]:
        lines.append(f"- {t}: {c} docs")
    open(os.path.join(HERE, "knowledge-report.md"), "w", encoding="utf-8").write("\n".join(lines))
    if "--json" in sys.argv:
        print(json.dumps({"doc_count": len(docs), "hot": hot[:10], "build_s": round(time.time()-t0, 2)}))
    else:
        print(f"indexed {len(docs)} docs in {time.time()-t0:.2f}s -> knowledge-index.json")

if __name__ == "__main__":
    main()
